arduino.globals:
#include <Keypad.h>

const byte ROWS_${COMP_SUFFIX} = 4;
const byte COLS_${COMP_SUFFIX} = 4;
char keys_${COMP_SUFFIX}[ROWS_${COMP_SUFFIX}][COLS_${COMP_SUFFIX}] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins_${COMP_SUFFIX}[ROWS_${COMP_SUFFIX}] = {${R1}, ${R2}, ${R3}, ${R4}};
byte colPins_${COMP_SUFFIX}[COLS_${COMP_SUFFIX}] = {${C1}, ${C2}, ${C3}, ${C4}};

Keypad keypad_${COMP_SUFFIX} = Keypad(makeKeymap(keys_${COMP_SUFFIX}), rowPins_${COMP_SUFFIX}, colPins_${COMP_SUFFIX}, ROWS_${COMP_SUFFIX}, COLS_${COMP_SUFFIX});

arduino.loop:
char key_${COMP_SUFFIX} = keypad_${COMP_SUFFIX}.getKey();
if (key_${COMP_SUFFIX}) {
  Serial.print("Key Pressed: ");
  Serial.println(key_${COMP_SUFFIX});
}
